### 1. 데이터 처리 파이프라인
```python
# 학생 성적 데이터 처리 예시
students = [
    {'name': '김철수', 'scores': [80, 90, 75]},
    {'name': '이영희', 'scores': [95, 88, 92]},
    {'name': '박민수', 'scores': [70, 65, 80]}
]

# 순수 함수들
def calculate_average(scores):
    return sum(scores) / len(scores)

def add_grade(student):
    avg = calculate_average(student['scores'])
    return {**student, 'average': avg, 'grade': 'A' if avg >= 90 else 'B' if avg >= 80 else 'C'}

def is_honor_student(student):
    return student['average'] >= 90

# 함수 조합으로 처리 파이프라인 구성
result = list(
    filter(is_honor_student,
        map(add_grade, students))
)
# 결과: 평균 90점 이상인 우등생만 필터링
```

