### 3. 복잡한 비즈니스 로직
```python
# 주문 처리 시스템 예시
from functools import reduce
from typing import List, Dict

def apply_discount(item, discount_rate=0.1):
    return {**item, 'discounted_price': item['price'] * (1 - discount_rate)}

def calculate_tax(item, tax_rate=0.1):
    price = item.get('discounted_price', item['price'])
    return {**item, 'tax': price * tax_rate}

def add_shipping_cost(total, shipping=5000):
    return total + shipping

# 주문 처리 함수 조합
def process_order(items: List[Dict]) -> Dict:
    # 각 아이템에 할인과 세금 적용
    processed_items = list(map(
        lambda item: calculate_tax(apply_discount(item)),
        items
    ))

    # 총 가격 계산
    subtotal = reduce(
        lambda total, item: total + item.get('discounted_price', item['price']) + item['tax'],
        processed_items,
        0
    )

    # 배송비 추가
    final_total = add_shipping_cost(subtotal)

    return {
        'items': processed_items,
        'subtotal': subtotal,
        'total': final_total
    }
```

### 4. 함수 합성을 활용한 유틸리티
```python
# 함수 합성 헬퍼
def compose(*functions):
    return lambda x: reduce(lambda acc, f: f(acc), functions, x)

# 문자열 처리 파이프라인
def trim_whitespace(text):
    return text.strip()

def to_lowercase(text):
    return text.lower()

def replace_spaces(text):
    return text.replace(' ', '_')

# 함수들을 합성한 새로운 함수
process_slug = compose(trim_whitespace, to_lowercase, replace_spaces)

# 사용
result = process_slug("  Hello World  ")  # "hello_world"
```

## 🎯 OOP와 비교한 실제 차이점

### OOP 방식:
```python
class ShoppingCart:
    def __init__(self):
        self.items = []
        self.total = 0

    def add_item(self, item):  # 상태 변경
        self.items.append(item)
        self.total += item['price']

    def apply_discount(self, rate):  # 기존 데이터 변경
        self.total *= (1 - rate)
```

### FP 방식:
