def add_item(cart, item):  # 새로운 cart 반환
    return {
        'items': cart['items'] + [item],
        'total': cart['total'] + item['price']
    }

def apply_discount(cart, rate):  # 새로운 cart 반환
    return {**cart, 'total': cart['total'] * (1 - rate)}
```

